<script setup>
import { computed, ref, watch } from 'vue'
import GadgetArt from './GadgetArt.vue'
import UiIcon from './UiIcon.vue'

const props = defineProps({
  user: { type: Object, default: null },
  config: { type: Object, default: () => ({ capabilities: {}, products: [], events: [] }) },
  gadgets: { type: Array, default: () => [] },
  orders: { type: Array, default: () => [] },
  loading: { type: Boolean, default: false },
  initialSection: { type: String, default: 'shop' },
})
const emit = defineEmits(['login', 'checkout', 'refresh-orders', 'refresh-order', 'close', 'open-gadget', 'open-event'])
const section = ref('shop')
watch(() => props.initialSection, value => { if (['shop', 'membership', 'orders'].includes(value)) section.value = value }, { immediate: true })
const productId = ref('keychain')
const gadgetId = ref('')
const quantity = ref(1)
const shipping = ref({ name: '', phone: '', province: '', city: '', district: '', address: '' })
const form = ref(null)
const defaultProducts = [
  { id: 'keychain', name: '口袋钥匙扣', amountCents: 1990, type: 'merchandise', description: '把一点小勇气，挂在每天的钥匙上。', icon: 'key', tone: 'honey' },
  { id: 'magnet', name: '奇妙冰箱贴', amountCents: 1490, type: 'merchandise', description: '每次打开冰箱，都收到一声小小的鼓励。', icon: 'star', tone: 'sage' },
  { id: 'postcards', name: '小奇迹明信片', amountCents: 2990, type: 'merchandise', description: '把收藏的快乐，寄给惦记的人。', icon: 'book', tone: 'rose' },
  { id: 'stand', name: '桌边小伙伴', amountCents: 2490, type: 'merchandise', description: '放在桌边，陪你认真工作、偶尔发呆。', icon: 'cloud', tone: 'lilac' },
]
const products = computed(() => {
  const configured = (props.config.products || []).filter(item => item.type === 'merchandise')
  return configured.length ? configured.map((item, index) => ({ ...defaultProducts[index % 4], ...item })) : defaultProducts
})
const selectedProduct = computed(() => products.value.find(item => item.id === productId.value) || products.value[0])
const selectedGadget = computed(() => props.gadgets.find(item => item.id === gadgetId.value) || null)
const membership = computed(() => (props.config.products || []).find(item => item.id === 'membership') || { id: 'membership', amountCents: 990 })
const paymentsOpen = computed(() => Boolean(props.config.capabilities?.payments))
const shopOpen = computed(() => paymentsOpen.value && Boolean(props.config.capabilities?.fulfillment))
const memberActive = computed(() => {
  const member = props.user?.membership
  if (member && typeof member === 'object') return member.active === true || (member.status === 'active' && (!member.expiresAt || timestamp(member.expiresAt) > Date.now()))
  const until = props.user?.membershipExpiresAt || props.user?.memberUntil || props.user?.membershipUntil
  return Boolean(until && timestamp(until) > Date.now())
})
const memberUntil = computed(() => props.user?.membership?.expiresAt || props.user?.membershipExpiresAt || props.user?.memberUntil || props.user?.membershipUntil)
const baseTotal = computed(() => Number(selectedProduct.value?.amountCents || 0) * clampQuantity(quantity.value))
const total = computed(() => Math.round(baseTotal.value * (memberActive.value ? .8 : 1)))
const checkoutAvailable = computed(() => shopOpen.value && Boolean(props.user) && Boolean(selectedGadget.value) && !props.loading)
const events = computed(() => props.config.events || [])
const features = [
  ['pocket', '每天多一点奇妙', '烦恼求助、盲盒和合体，尽情去探索。'],
  ['star', '遇见传说道具', '开启传说口袋，让稀有的小奇迹更近一点。'],
  ['share', '留下一张好明信片', '高清无水印导出，珍藏属于你的故事。'],
  ['tool', '小道具更快回来', '修理时间减半，喜欢的小伙伴少等一会儿。'],
  ['gift', '把快乐带回家', '定制小物享八折，专属成就也一起收好。'],
]
const statusNames = { awaiting_payment: '待付款', pending: '待付款', paid: '已付款', processing: '制作中', shipped: '已发货', delivered: '已送达', completed: '已完成', cancelled: '已取消', refunded: '已退款', failed: '未完成' }

watch(() => props.gadgets, gadgets => { if (!gadgets.some(item => item.id === gadgetId.value)) gadgetId.value = gadgets[0]?.id || '' }, { immediate: true })
watch(products, value => { if (!value.some(item => item.id === productId.value)) productId.value = value[0]?.id || '' }, { immediate: true })
function money(cents) { const value = Number(cents); return Number.isFinite(value) ? (value / 100).toFixed(2).replace(/\.00$/, '') : '—' }
function timestamp(value) { return typeof value === 'number' ? value : /^\d+$/.test(String(value)) ? Number(value) : Date.parse(value) }
function date(value) { if (/^\d{2}-\d{2}$/.test(String(value))) return `${Number(value.slice(0,2))}月${Number(value.slice(3))}日`; const parsed = new Date(timestamp(value)); return value && !Number.isNaN(parsed.getTime()) ? parsed.toLocaleDateString('zh-CN', { timeZone: 'Asia/Shanghai', year: 'numeric', month: 'numeric', day: 'numeric' }) : '' }
function clampQuantity(value) { return Math.max(1, Math.min(10, Math.trunc(Number(value) || 1))) }
function adjustQuantity(change) { quantity.value = clampQuantity(clampQuantity(quantity.value) + change) }
function submitOrder() {
  if (!checkoutAvailable.value || !form.value?.reportValidity()) return
  emit('checkout', { productId: selectedProduct.value.id, gadgetId: selectedGadget.value.id, quantity: clampQuantity(quantity.value), shipping: Object.fromEntries(Object.entries(shipping.value).map(([key, value]) => [key, value.trim()])) })
}
function buyMembership() { if (props.user && paymentsOpen.value && !props.loading) emit('checkout', { productId: 'membership', quantity: 1 }) }
function eventUnlocked(event) { return props.user?.seasonalUnlocks?.includes(event.id) === true }
function buyEvent(event) {
  if (eventUnlocked(event) && !props.loading) { emit('open-event', event.id); return }
  if (props.user && paymentsOpen.value && event.active && !props.loading) emit('checkout', { productId: 'seasonal', eventId: event.id })
}
function orderTitle(order) { return order.name || order.productName || order.product?.name || (order.productId === 'membership' ? '口袋月卡' : order.productId === 'seasonal' ? '节日限定小口袋' : products.value.find(item => item.id === order.productId)?.name) || '奇妙小物订单' }
function orderAmount(order) { return order.amountCents ?? order.totalCents ?? order.totalAmountCents ?? order.total ?? 0 }
function orderStatus(order) { return order.status === 'paid' && ['processing','shipped','delivered','completed'].includes(order.fulfillment?.status) ? order.fulfillment.status : order.status }
function trackingNumber(order) { return order.fulfillment?.trackingNumber || order.tracking?.number || order.trackingNumber || '' }
function carrier(order) { return order.fulfillment?.carrier || order.tracking?.carrier || order.carrier || '配送中' }
function paymentLink(order) { try { const link = new URL(order.checkoutUrl || order.paymentUrl); return ['https:','http:'].includes(link.protocol) && !link.username && !link.password ? link.href : '' } catch { return '' } }
</script>

<template>
  <section class="inner-page commerce-page">
    <div class="page-intro"><span class="eyebrow"><UiIcon name="gift" :size="17" /> 给生活留一点小小的仪式感</span><h1>把奇妙，<span class="highlight-word">放在身边</span></h1><p>让口袋里的故事，变成陪你过日子的小物件。</p></div>
    <nav class="shop-tabs" aria-label="奇妙商店分类"><button v-for="[id,label,icon] in [['shop','奇妙小物','gift'],['membership','口袋月卡','star'],['orders','我的订单','book']]" :key="id" :class="{active:section===id}" :aria-current="section===id?'page':undefined" @click="section=id"><UiIcon :name="icon" :size="17" />{{ label }}<span v-if="id==='orders' && orders.length" class="order-count">{{ orders.length }}</span></button></nav>

    <template v-if="section === 'shop'">
      <div class="shop-note"><UiIcon name="heart" :size="19" /><p>每件小物，都可以印上你发现的原创道具。<span v-if="!shopOpen">柜台正在准备中，先挑一个喜欢的吧。</span><span v-else>挑好道具，留下一份属于你的童年纪念。</span></p><span class="note-stamp">MADE OF WONDER</span></div>
      <div class="product-grid"><button v-for="product in products" :key="product.id" class="product-card" :class="[product.tone,{selected:productId===product.id}]" :aria-pressed="productId===product.id" @click="productId=product.id"><div class="product-art"><div class="product-object" :class="product.icon"><span v-if="product.icon==='key'" class="key-ring"></span><span v-if="product.icon==='book'" class="postcard-back"></span><GadgetArt :kind="selectedGadget?.kind || product.icon" :color="selectedGadget?.color || '#d4ab62'" /><span v-if="product.icon==='book'" class="postcard-caption">a little bit of wonder</span></div><span class="product-spark">✧</span><span v-if="productId===product.id" class="product-check"><UiIcon name="check" :size="15" /></span></div><div class="product-copy"><div><h2>{{ product.name }}</h2><span class="product-price">¥{{ money(product.amountCents) }}</span></div><p>{{ product.description }}</p></div></button></div>
      <form ref="form" class="custom-order" @submit.prevent="submitOrder">
        <div class="order-customization"><span class="section-kicker">YOUR OWN LITTLE KEEPSAKE</span><h2>给它，印上你的小奇妙。</h2><p class="custom-subtitle">已发现的道具，都能成为专属图案。</p><div v-if="!gadgets.length" class="no-gadgets"><UiIcon name="pocket" :size="30" /><p>口袋还没打开呢。<br>先去发现一件道具，再把它带回家。</p></div><template v-else><label class="field-label" for="shop-gadget">选择你的道具</label><select id="shop-gadget" v-model="gadgetId" :disabled="loading"><option v-for="gadget in gadgets" :key="gadget.id" :value="gadget.id">{{ gadget.name }}</option></select><div class="chosen-gadget"><GadgetArt :kind="selectedGadget?.kind" :color="selectedGadget?.color" /><div><strong>{{ selectedGadget?.name }}</strong><p>{{ selectedGadget?.effect }}</p><button type="button" class="text-button" @click="emit('open-gadget',selectedGadget)">再看看这件道具 <UiIcon name="arrow" :size="14" /></button></div></div></template><div class="quantity-row"><label for="shop-quantity">想带走几份？</label><div class="quantity-control"><button type="button" aria-label="减少数量" :disabled="quantity<=1 || loading" @click="adjustQuantity(-1)">−</button><input id="shop-quantity" v-model.number="quantity" type="number" min="1" max="10" step="1" required :disabled="loading" @blur="quantity=clampQuantity(quantity)"><button type="button" aria-label="增加数量" :disabled="quantity>=10 || loading" @click="adjustQuantity(1)">+</button></div></div><p class="quantity-note">每单最多 10 份，快乐也可以分给朋友。</p></div>
        <div class="shipping-panel"><h2><UiIcon name="gift" :size="18" /> 把小奇妙寄到这里</h2><div class="shipping-fields"><label>收件人<input v-model="shipping.name" autocomplete="shipping name" maxlength="40" placeholder="怎么称呼你" required :disabled="loading"></label><label>联系电话<input v-model="shipping.phone" type="tel" autocomplete="shipping tel" inputmode="tel" pattern="1[3-9][0-9]{9}" maxlength="11" placeholder="11 位手机号码" title="请填写有效的 11 位手机号码" required :disabled="loading"></label><div class="region-fields"><label>省 / 直辖市<input v-model="shipping.province" autocomplete="shipping address-level1" maxlength="30" placeholder="例如：浙江省" required :disabled="loading"></label><label>城市<input v-model="shipping.city" autocomplete="shipping address-level2" maxlength="30" placeholder="例如：杭州市" required :disabled="loading"></label><label>区 / 县<input v-model="shipping.district" autocomplete="shipping address-level3" maxlength="30" placeholder="例如：西湖区" required :disabled="loading"></label></div><label class="address-field">详细地址<textarea v-model="shipping.address" autocomplete="shipping street-address" maxlength="200" rows="2" placeholder="街道、门牌号等详细信息" required :disabled="loading"></textarea></label></div><div class="order-total"><span>{{ selectedProduct?.name }} × {{ quantity || 1 }}<small v-if="memberActive">月卡专属八折 <s>¥{{ money(baseTotal) }}</s></small></span><strong>¥{{ money(total) }}</strong></div><p class="price-note">最终金额和配送费用，以订单确认时显示为准。</p><button class="primary-button" type="submit" :disabled="!checkoutAvailable"><UiIcon name="gift" :size="18" />{{ loading ? '正在准备订单…' : !shopOpen ? '小物柜台即将开张' : !user ? '登录后即可定制' : !gadgets.length ? '先去发现一件道具吧' : '确认这份小奇妙' }}<UiIcon name="arrow" :size="18" /></button><button v-if="!user" class="text-button login-link" type="button" @click="emit('login')">登录，保存我的订单 <UiIcon name="arrow" :size="15" /></button><p class="shipping-footnote">收件信息仅用于这次订单的制作与配送。</p></div>
      </form>
      <section class="seasonal-section"><div class="seasonal-heading"><div><span class="section-kicker">A SPECIAL LITTLE POCKET</span><h2>节日，给奇妙多一个借口。</h2></div><span class="seasonal-badge">限定小口袋</span></div><div v-if="!events.length" class="seasonal-empty"><UiIcon name="spark" :size="29" /><div><strong>下一份节日惊喜，还在口袋里。</strong><p>新的主题道具准备好了，会在这里与你见面。</p></div></div><div v-else class="seasonal-grid"><article v-for="event in events" :key="event.id" class="seasonal-card"><div class="event-art"><GadgetArt :kind="event.kind || 'balloon'" :color="event.color || '#c8a26a'" /></div><div><span class="event-state">{{ event.active ? '限时见面中' : '等待开场' }}</span><h3>{{ event.name }}</h3><p>{{ event.description }}</p><small v-if="event.start && event.end">{{ date(event.start) }} — {{ date(event.end) }}</small><div class="event-buy"><strong>¥{{ money(event.priceCents ?? 600) }} <span>/ 主题</span></strong><button type="button" class="text-button" :disabled="loading || (!eventUnlocked(event) && (!paymentsOpen || !user || !event.active))" @click="buyEvent(event)">{{ eventUnlocked(event) ? '已解锁，随机掏一个' : !paymentsOpen || !event.active ? '暂未开放' : !user ? '登录后开启' : '开启限定口袋' }}<UiIcon name="arrow" :size="15" /></button></div></div></article></div></section>
    </template>

    <template v-else-if="section === 'membership'">
      <div class="membership-layout"><article class="membership-card"><span class="member-card-number">WONDER POCKET · MONTHLY PASS</span><div class="member-mark"><UiIcon name="pocket" :size="55" /><span>✧</span></div><span class="member-kicker">一张月卡，多一点孩子气</span><h2>奇妙口袋月卡</h2><div class="member-price"><span>¥</span>{{ money(membership.amountCents) }}<small>/ 月</small></div><p>偶尔需要魔法的人，<br>都可以在这里多待一会儿。</p><div class="member-bottom"><span>KEEP A LITTLE WONDER</span><UiIcon name="star" :size="20" /></div></article><div class="membership-details"><span class="section-kicker">A LITTLE MORE MAGIC</span><h2>{{ memberActive ? '小奇妙，正在陪伴你。' : '让口袋，为你多留一盏灯。' }}</h2><p v-if="memberActive" class="member-state"><UiIcon name="check" :size="16" />月卡生效中<span v-if="memberUntil"> · 至 {{ date(memberUntil) }}</span></p><ul class="member-features"><li v-for="[icon,title,description] in features" :key="title"><span><UiIcon :name="icon" :size="21" /></span><div><strong>{{ title }}</strong><p>{{ description }}</p></div></li></ul><button class="primary-button" :disabled="!paymentsOpen || !user || loading" @click="buyMembership"><UiIcon name="star" :size="18" />{{ loading ? '正在准备订单…' : !paymentsOpen ? '月卡柜台即将开放' : !user ? '登录后开通月卡' : memberActive ? '再续一个月的小奇妙' : '开通口袋月卡' }}<UiIcon name="arrow" :size="18" /></button><button v-if="!user" class="text-button login-link" @click="emit('login')">先登录我的口袋 <UiIcon name="arrow" :size="15" /></button><p class="member-note">{{ paymentsOpen ? '购买成功后生效，不自动续费。' : '月卡还在准备中，基础玩法可以继续免费体验。' }}</p></div></div>
    </template>

    <template v-else>
      <div class="orders-heading"><div><h2>寄向生活的小小奇妙</h2><p>每份订单的进展，都在这里等你来看。</p></div><button class="text-button" :disabled="!user || loading" @click="emit('refresh-orders')"><UiIcon name="shuffle" :size="15" />{{ loading ? '正在查看…' : '刷新订单' }}</button></div><div v-if="!user" class="orders-empty"><UiIcon name="gift" :size="44" /><h3>登录后，找到你的那一份。</h3><p>订单和物流会跟着你的账号好好保存。</p><button class="primary-button" @click="emit('login')">登录查看我的订单 <UiIcon name="arrow" :size="18" /></button></div><div v-else-if="!orders.length" class="orders-empty"><UiIcon name="gift" :size="44" /><h3>还没有小奇妙出发。</h3><p>{{ loading ? '正在翻找你的订单，请稍等一会儿。' : '喜欢的道具，可以先留在收藏里。' }}</p><button class="text-button" @click="section='shop'">去小物柜台逛一逛 <UiIcon name="arrow" :size="16" /></button></div><div v-else class="orders-list"><article v-for="order in orders" :key="order.id" class="order-card"><header><span>订单 {{ order.number || order.orderNo || order.id }}</span><span class="order-status" :class="orderStatus(order)">{{ statusNames[orderStatus(order)] || '处理中' }}</span></header><div class="order-main"><span class="order-icon"><UiIcon :name="order.productId==='membership'?'star':'gift'" :size="30" /></span><div><h3>{{ orderTitle(order) }}</h3><p>{{ order.gadgetName || order.gadget?.name || (order.productId==='membership'?'给生活多留一点魔法':'属于你的原创小奇妙') }}<span v-if="order.quantity"> · {{ order.quantity }} 份</span></p><small v-if="order.createdAt">{{ date(order.createdAt) }}</small></div><strong>¥{{ money(orderAmount(order)) }}</strong></div><div v-if="trackingNumber(order) || order.fulfillment?.carrier || order.tracking" class="tracking-row"><UiIcon name="gift" :size="15" /><span>{{ carrier(order) }}<span v-if="trackingNumber(order)"> · 运单号 {{ trackingNumber(order) }}</span></span></div><p v-if="order.shippingSummary || order.shipping?.name" class="order-address">寄给 {{ order.shippingSummary?.name || order.shipping?.name }} · {{ order.shippingSummary?.region || [order.shipping?.province,order.shipping?.city,order.shipping?.district].filter(Boolean).join(' ') }}</p><footer><p>{{ order.status==='awaiting_payment' ? '完成付款后，这份奇妙才会出发。' : orderStatus(order)==='processing' ? '小物正在认真制作，请再等一等。' : orderStatus(order)==='shipped' ? '小奇妙已经出发，路上见。' : order.status==='refunded' ? '款项已退款，期待下次再见。' : '' }}</p><div class="order-footer-actions"><a v-if="order.status==='awaiting_payment' && paymentLink(order)" class="order-payment" :href="paymentLink(order)" target="_blank" rel="noopener noreferrer">继续付款 <UiIcon name="arrow" :size="14" /></a><button class="text-button" :disabled="loading" @click="emit('refresh-order',order.id)">查看最新进展 <UiIcon name="arrow" :size="15" /></button></div></footer></article></div>
    </template>
  </section>
</template>

